# Print all phone contacts with their relationships to identify which are "friends"
for c in all_contacts:
    print(f"ID: {c['contact_id']}, Name: {c['first_name']} {c['last_name']}, Email: {c['email']}, Relationships: {c['relationships']}")

# Inspect all phone contacts and their relationships to identify which are friends.
for contact in all_phone_contacts:
    print(f"{contact['first_name']} {contact['last_name']}: {contact['relationships']}")

