steps.code:
# Let's get all Spotify playlists (paginated)
playlists = []
page = 0
while True:
    result = apis.spotify.show_playlist_library(access_token=spotify_login['access_token'], page_index=page, page_limit=20)
    if isinstance(result, list):
        playlists.extend(result)
        if len(result) < 20:
            break
        page += 1
    else:
        print("Error:", result)
        break
print(f"Total playlists: {len(playlists)}")
for p in playlists:
    print(p['playlist_id'], p['title'])

