for pl in all_playlists_now:
    if pl['playlist_id'] == 654:
        continue  # skip the archived playlist
    pl_song_ids = pl['song_ids']
    overlap = matched_set.intersection(pl_song_ids)
    if overlap:
        remaining_pairs.append((pl['playlist_id'], sorted(overlap)))
        print(f"Playlist {pl['playlist_id']} still contains matched songs: {sorted(overlap)}")

if not remaining_pairs:
