steps.code:
# Parse the archive file content into a list of (title, artist) pairs
archive_songs = []
for line in file_data['content'].split('\n'):
    line = line.strip()
    if line.startswith('- '):
        # Remove the leading "- " and split on " by "
        song_str = line[2:]
        if ' by ' in song_str:
            title, artist = song_str.split(' by ', 1)
            archive_songs.append((title.strip(), artist.strip()))

print(f"Parsed {len(archive_songs)} songs to archive")
for title, artist in archive_songs:
    print(f"  {title} by {artist}")

