{
 "app_name": "spotify",
 "api_name": "show_playlist_library",
 "path": "/library/playlists",
 "method": "GET",
 "description": "Get a list of playlists in the user's playlist library.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from spotify app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "is_public",
   "type": "boolean",
   "required": false,
   "description": "Whether to show public playlists or private playlists.",
   "default": null,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1.0, <= 20.0"
   ]
  }
 ],
 "response_schemas": {
  "success": [
   {
    "playlist_id": 1,
    "title": "string",
    "is_public": true,
    "rating": 0.0,
    "like_count": 1,
    "review_count": 1,
    "owner": {
     "name": "string",
     "email": "user@example.com"
    },
    "created_at": "2019-01-01T00:00:00",
    "song_ids": [
     1
    ]
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}

