# Let's verify the archived song IDs and check if any remain in the playlists
print("Archived song IDs:", [song_id for song_id, _, _ in song_ids_to_archive])
print("\nArchived song details:")
for song_id, title, artist in song_ids_to_archive:
    print(f"  ID {song_id}: {title} by {artist}")

# Check if any archived song remains in any playlist except 654
archived_ids = {song_id for song_id, _, _ in song_ids_to_archive}
remaining_archived = []
for playlist in all_playlists:
    if playlist["playlist_id"] == 654:
        continue
    for song_id in playlist["song_ids"]:
        if song_id in archived_ids:
            remaining_archived.append((playlist["playlist_id"], playlist["title"], song_id))

if remaining_archived:
    print("\nWARNING: Archived songs still present in other playlists:")
    for pid, title, sid in remaining_archived:
        print(f"  Playlist {pid} ({title}) contains song_id {sid}")
else:
    print("\nAll archived songs have been successfully removed from all playlists except 'Old Songs'.")

